	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// Validate input IDs
		for _, id := range ids {
			if strings.ContainsRune(id, 0) || !utf8.ValidString(id) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 400}
			}
		}

		// Compute requestHash: SHA-256("bulk-approve.v3\n" + sorted IDs formatted as "<utf8-length>:<id>")
		requestHash := computeRequestHash(ids)

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		// Set session config for RLS
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Check for existing idempotency key with same scope (operation+tenant+actor+key)
		// Scope: operation="bulk-approve.v3", tenant=u.Tenant, actor=u.User, key=key
		var existingHash, existingResponse string
		var existingRequestHash string
		err = tx.QueryRow(ctx,
			`SELECT "requestHash", response FROM "ActionRequest" 
			 WHERE "tenantId"=$1 AND "actorId"=$2 AND operation='bulk-approve.v3' AND key=$3`,
			u.Tenant, u.User, key).
			Scan(&existingRequestHash, &existingResponse)

		if err == nil {
			// Key exists - check if same request (same idempotency set)
			if existingRequestHash != requestHash {
				// Same key, different target set -> 409
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			// Same key, same targets -> replay
			var result protocol.Result
			if err := json.Unmarshal([]byte(existingResponse), &result); err != nil {
				return protocol.Result{}, false, err
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return result, true, nil
		} else if err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		// New request - validate targets exist and are eligible for approval
		rows, err := tx.Query(ctx,
			`SELECT id FROM "Purchase" WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted' ORDER BY id FOR UPDATE`,
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// All targets must be eligible; if any is invalid, reject all
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 400}
		}

		// Update purchases to approved status
		tag, err := tx.Exec(ctx,
			`UPDATE "Purchase" SET status='approved' WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`,
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Create approval audit records for each approved purchase
		for _, id := range ids {
			_, err := tx.Exec(ctx,
				`INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
				 VALUES ($1, $2, $3, 'bulk-approve.v3', $4, 'submitted', 'approved')`,
				u.Tenant, id, u.User, key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		// Create action request record
		result := protocol.Result{ApprovedIDs: ids}
		responseJSON, err := json.Marshal(result)
		if err != nil {
			return protocol.Result{}, false, err
		}

		_, err = tx.Exec(ctx,
			`INSERT INTO "ActionRequest" ("tenantId", "actorId", operation, key, "requestHash", response)
			 VALUES ($1, $2, 'bulk-approve.v3', $3, $4, $5)`,
			u.Tenant, u.User, key, requestHash, responseJSON)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return result, false, nil
	}

	return protocol.HTTP(approve, fallback), nil
}

// computeRequestHash computes SHA-256 of "bulk-approve.v3\n" followed by sorted IDs formatted as "<utf8-length>:<id>"
func computeRequestHash(ids []string) string {
	h := sha256.New()
	h.Write([]byte("bulk-approve.v3\n"))
	for _, id := range ids {
		idBytes := []byte(id)
		h.Write([]byte(fmt.Sprintf("%d:%s", len(idBytes), id)))
	}
	return hex.EncodeToString(h.Sum(nil))
}

